package com.pratik.imagetap;
import android.app.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="w412dp-h892dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class PresetTransferUiTest {
 @Test public void exportUsesSystemCreateDocument(){Intent start=new Intent(RuntimeEnvironment.getApplication(),PresetTransferActivity.class).putExtra("export",true).putExtra("slot",0);org.robolectric.android.controller.ActivityController<PresetTransferActivity> ctl=Robolectric.buildActivity(PresetTransferActivity.class,start).setup();PresetTransferActivity a=ctl.get();Intent picker=Shadows.shadowOf(a).getNextStartedActivity();assertEquals(Intent.ACTION_CREATE_DOCUMENT,picker.getAction());assertEquals("application/zip",picker.getType());assertTrue(picker.getStringExtra(Intent.EXTRA_TITLE).endsWith(".autobash.zip"));a.finish();ctl.pause().stop().destroy();}
 @Test public void importUsesSystemOpenDocumentAndShowsThreeSlots()throws Exception{Intent start=new Intent(RuntimeEnvironment.getApplication(),PresetTransferActivity.class);org.robolectric.android.controller.ActivityController<PresetTransferActivity> ctl=Robolectric.buildActivity(PresetTransferActivity.class,start).setup();PresetTransferActivity a=ctl.get();assertEquals(Intent.ACTION_OPEN_DOCUMENT,Shadows.shadowOf(a).getNextStartedActivity().getAction());Bitmap b=Bitmap.createBitmap(16,16,Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);TargetStore.save(a,b);b.recycle();ByteArrayOutputStream out=new ByteArrayOutputStream();PresetArchive.exportSlot(a,0,out);PresetArchive.Staged staged=PresetArchive.stage(a,new ByteArrayInputStream(out.toByteArray()));Field f=PresetTransferActivity.class.getDeclaredField("staged");f.setAccessible(true);f.set(a,staged);Method preview=PresetTransferActivity.class.getDeclaredMethod("preview");preview.setAccessible(true);preview.invoke(a);AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();View root=dialog.getWindow().getDecorView();assertEquals(3,Release67Test.views(root,RadioButton.class).size());assertEquals("Replace slot & import",dialog.getButton(-1).getText().toString());AutoBashUiTest.save(root,"preset-import67",760,1100);dialog.getButton(-2).performClick();ctl.pause().stop().destroy();assertFalse(staged.folder.exists());}
}
